(()=>{
'use strict';const $=s=>document.querySelector(s),money=v=>(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});let config=null,order=null,pollTimer,busy=false;
const status=(text,error=false)=>{$('#pix-message').textContent=text;$('#pix-message').dataset.error=String(error)};const method=()=>document.querySelector('[name=shipping-method]:checked')?.value||'pac';
const api=async body=>{const r=await fetch('/api/pix',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(55000)});let data;try{data=await r.json()}catch{throw Error('Não foi possível conectar ao pagamento. Tente novamente.')};if(!r.ok){const error=Error(data.error||'Pagamento indisponível.');error.httpStatus=r.status;throw error}return data};
function updateTotals(){const cart=window.checkoutCart||[];const subtotal=cart.reduce((s,i)=>s+i.quantity*i.price,0);const fee=method()==='sedex'?990:0;$('#shipping-total').textContent=fee?money(fee):'Grátis';$('#checkout-total').textContent=money(subtotal+fee);$('[data-summary-total]').textContent=money(subtotal+fee);$('#pix-amount').textContent=money(subtotal+fee)}
function save(){if(order)sessionStorage.setItem('growth-pix-order-v1',JSON.stringify({id:order.id,accessToken:order.accessToken,state:order.state,message:order.message,errorCode:order.errorCode,fingerprint:order.fingerprint}))}
function fingerprint(){return JSON.stringify({items:(window.checkoutCart||[]).map(i=>({id:i.id,quantity:i.quantity,options:i.options})),shipping:method()})}
function lockForm(locked){document.querySelectorAll('#identity-form input,#address-form input,#address-form select,#step-3 [data-back]').forEach(e=>e.disabled=locked);}
function render(data){if(['pac','sedex'].includes(data.shippingMethod))document.querySelector('[name=shipping-method][value='+data.shippingMethod+']').checked=true;order={...order,...data};save();$('#pix-amount').textContent=money(data.amount);$('#checkout-total').textContent=money(data.amount);$('[data-summary-total]').textContent=money(data.amount);$('#shipping-total').textContent=data.shipping?money(data.shipping):'Grátis';$('#generate-pix').hidden=data.state!=='quoted';if(data.state==='quoted')$('#generate-pix').disabled=!config?.ready;$('#pix-code-panel').hidden=!data.pixCode||!['pending','processing'].includes(data.state);$('#pix-paid').hidden=data.state!=='paid';lockForm(!['quoted','rejected'].includes(data.state));if(data.pixCode){$('#pix-code').value=data.pixCode;$('#pix-qr').src=data.qrCode;$('#pix-qr').hidden=!data.qrCode}if(data.expiresAt){const date=new Date(data.expiresAt);$('#pix-expiration').textContent=Number.isNaN(date.getTime())?'':'Válido até '+date.toLocaleString('pt-BR')}
 const messages={rejected:data.message||'A operadora recusou a solicitação. Revise os dados antes de tentar novamente.',unknown:data.message||order.message||'Não foi possível recuperar a resposta da operadora. Confira seu pedido com a loja antes de tentar gerar outro Pix.',quoted:'',processing:'Aguardando resposta da operadora. Não gere outro pedido enquanto verificamos.',pending:data.pixCode?'Escaneie o QR Code ou copie o código para pagar no aplicativo do seu banco.':'Seu Pix está sendo preparado. Aguarde a confirmação da operadora.',paid:'Pagamento confirmado pela operadora.',expired:'Este Pix expirou. Volte ao carrinho para iniciar um novo pedido.',canceled:'Este pagamento foi cancelado.',refunded:'Este pagamento foi estornado.'};status(messages[data.state]??'Verificando pagamento…',['unknown','rejected'].includes(data.state));$('#pix-review-rejected').hidden=data.state!=='rejected';$('#pix-check-recovery').hidden=data.state!=='unknown';
 if(data.state==='paid'){$('#pix-order-id').textContent='Pedido '+data.id;clearTimeout(pollTimer);return}if(['pending','processing'].includes(data.state)){clearTimeout(pollTimer);pollTimer=setTimeout(check,10000)}}
async function check(){if(!order||busy)return;busy=true;try{render(await api({action:'status',id:order.id,accessToken:order.accessToken}))}catch(e){status(e.message,true);clearTimeout(pollTimer);pollTimer=setTimeout(check,15000)}finally{busy=false}}
async function prepare(){updateTotals();if(!config?.ready){status('Pagamento ainda indisponível. Tente novamente mais tarde.',true);return}if(order&&order.state!=='quoted'){await check();return}$('#generate-pix').disabled=true;status('Conferindo produtos e valor do pedido…');try{const data=await api({action:'quote',items:(window.checkoutCart||[]).map(i=>({id:i.id,quantity:i.quantity,options:i.options||{}})),shippingMethod:method()});order={...data,state:'quoted',fingerprint:fingerprint()};save();render(order);$('#generate-pix').disabled=false}catch(e){status(e.message)}}
$('#generate-pix').onclick=async()=>{if(busy||!order)return;busy=true;$('#generate-pix').disabled=true;lockForm(true);status('Gerando seu Pix…');const get=id=>$('#'+id).value.trim();const customer={name:get('name'),email:get('email'),phone_number:get('phone'),document:get('document'),street_name:get('street'),number:get('number'),complement:get('complement'),neighborhood:get('district'),city:get('city'),state:get('state'),zip_code:get('zip')};order.state='processing';save();try{render(await api({action:'create',id:order.id,accessToken:order.accessToken,customer}))}catch(e){if([400,409].includes(e.httpStatus)){render({...order,state:'quoted'});status(e.message,true);return}render({...order,state:'unknown'});status(e.message+' Consulte este pedido antes de tentar gerar outro Pix.',true);pollTimer=setTimeout(check,10000)}finally{busy=false}};
$('#pix-review-rejected').onclick=()=>{if(order?.state!=='rejected')return;clearTimeout(pollTimer);order=null;sessionStorage.removeItem('growth-pix-order-v1');location.reload()};
$('#new-purchase').onclick=()=>{if(order?.state==='paid'){if(order.fingerprint===fingerprint())localStorage.setItem('growth-cart-v1','[]');sessionStorage.removeItem('growth-pix-order-v1');location.href='/'}};
$('#copy-pix').onclick=async()=>{try{await navigator.clipboard.writeText($('#pix-code').value);status('Código Pix copiado. Cole no aplicativo do seu banco.')}catch{$('#pix-code').focus();$('#pix-code').select();status('Selecione e copie o código Pix acima.')}};$('#check-pix').onclick=check;$('#pix-check-recovery').onclick=check;
for(const e of document.querySelectorAll('[name=shipping-method]'))e.addEventListener('change',()=>{if(order?.state==='quoted'){order=null;sessionStorage.removeItem('growth-pix-order-v1')}updateTotals()});
window.addEventListener('checkout:ready',updateTotals);window.addEventListener('checkout:payment',prepare);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&order&&['pending','processing'].includes(order.state))check()});
(async()=>{try{const r=await fetch('/api/pix');config=await r.json()}catch{config={ready:false}}updateTotals();if(config.ready){try{const previous=JSON.parse(sessionStorage.getItem('growth-pix-order-v1'));if(previous?.id&&previous.accessToken&&previous.state!=='quoted'){order=previous;await check();$('#step-1').hidden=true;$('#step-2').hidden=true;$('#step-3').hidden=false;document.querySelectorAll('.progress li').forEach((li,i)=>{li.classList.toggle('current',i===2);li.classList.toggle('complete',i<2);if(i===2)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current')})}}catch{} if(!$('#step-3').hidden&&!order)prepare();}})();
})();
